/**
 * THE CARD-MESSAGE FACE for the printed six-panel form and the plain
 * ticket: Cormorant Garamond, Medium Italic, the site's own display family
 * (Kevin, 2026-10-14: "a bit prettier"). SIL Open Font License 1.1
 * (CormorantGaramond-OFL.txt beside this file).
 *
 * HOW THIS FILE WAS MADE, because the obvious route failed: Google's
 * static instance of this face has glyphs fontkit cannot parse, and a
 * ticket drawn with it lost most of its letters. This is the variable
 * italic from github.com/google/fonts (ofl/cormorantgaramond), instanced
 * at wght=500 with fontTools.varLib.instancer and subset to Latin
 * (U+0020-017F plus the common punctuation block) with fontTools.subset,
 * which fontkit reads cleanly. Embedded as base64 like the email logo,
 * because a file read at runtime is not something a serverless bundle can
 * be trusted to find; pdf-lib subsets it again per ticket.
 */
export const CARD_FONT_BASE64 =
  "";
